 need(entries==[(1,7,0xffffffff),(4,7,0xffffffff),(8,7,TSS),(16,7,0xffffffff),(32,5,0xffffffff)],'exact source-derived TPM permissions/group')
 return dict(attribute=ATTR,version=2,entries=[dict(tag=t,permissions=p,id=None if i==0xffffffff else i)for t,p,i in entries],hex=raw.hex())
